    const groups = $input.all().map(i => i.json).filter(g => g.product_id);
    if (!groups.length) return [{ json: { noWork: true } }];

    const describe = key => {
      const [employment, income, score] = key.split('|');
      return `${employment}, net monthly income ${income}, credit score ${score}`;
    };

    const instructions = `You are a loan eligibility analyst for an Indian lending marketplace.
Every profile below ALREADY meets this product's numeric criteria (minimum income, credit score, age, employment type); a database checked those.
Judge ONLY the product's qualitative rules for each profile.
We do not know employer name, salary account, education, city or years of experience. Do NOT reject a profile because such a fact is unknown.
Reject only when the profile contradicts a rule (e.g. rule is for government employees and profile is Business) or when a stricter tier clearly cannot be met (e.g. income band is entirely below the only stated income tier for that employment type).
For each profile return eligible true/false and a reason of at most 20 words written for the customer.`;

    // One request per product, all of its profiles together (chunks of 45 = every possible profile).
    const byProduct = {};
    for (const g of groups) (byProduct[g.product_id] ??= []).push(g);

    const requests = [];
    for (const list of Object.values(byProduct)) {
      for (let i = 0; i < list.length; i += 45) {
        const chunk = list.slice(i, i + 45);
        const p = chunk[0];
        const prompt = `Product: ${p.lender} – ${p.product_name}\nQualitative rules: ${p.eligibility_notes}\n\nProfiles:\n` +
          chunk.map(g => `- profile_key "${g.profile_key}": ${describe(g.profile_key)} (${g.users} users)`).join('\n');
        requests.push({
          json: {
            product_id: p.product_id,
            notes_md5: p.notes_md5,
            profile_keys: chunk.map(g => g.profile_key),
            users_covered: chunk.reduce((n, g) => n + Number(g.users), 0),
            geminiRequest: {
              systemInstruction: { parts: [{ text: instructions }] },
              contents: [{ role: 'user', parts: [{ text: prompt }] }],
              generationConfig: {
                temperature: 0,
                responseMimeType: 'application/json',
                responseSchema: {
                  type: 'OBJECT',
                  properties: {
                    verdicts: {
                      type: 'ARRAY',
                      items: {
                        type: 'OBJECT',
                        properties: {
                          profile_key: { type: 'STRING' },
                          eligible: { type: 'BOOLEAN' },
                          reason: { type: 'STRING' },
                        },
                        required: ['profile_key', 'eligible', 'reason'],
                      },
                    },
                  },
                  required: ['verdicts'],
                },
              },
            },
          },
        });
      }
    }
    return requests;

const req = $('For each LLM request').item.json;
let verdicts = [];
let error = null;
try {
  const text = $json.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('') || '';
  verdicts = JSON.parse(text).verdicts || [];
} catch (e) {
  // No verdict is stored, so these profiles stay unmatched now and are retried next run.
  error = $json.error?.message || `Could not parse LLM output: ${e.message}`;
}
const asked = new Set(req.profile_keys);
const rows = verdicts
  .filter(v => asked.has(v.profile_key) && typeof v.eligible === 'boolean')
  .map(v => ({
    product_id: req.product_id,
    profile_key: v.profile_key,
    notes_md5: req.notes_md5,
    eligible: v.eligible,
    reason: String(v.reason || '').slice(0, 300),
  }));
return { json: { product_id: req.product_id, asked: asked.size, answered: rows.length, error, rowsJson: JSON.stringify(rows) } };
